const op=String($json.operation||'append').toLowerCase();
const allowed=['append','put','get','recent','find_request'];
if(!allowed.includes(op)) throw new Error(`Unsupported memory operation: ${op}`);
const request_id=String($json.request_id||'');
const key=String($json.key||request_id||'default');
const limit=Math.max(1,Math.min(Number($json.limit||50),500));
return [{json:{operation:op,request_id,key,value:$json.value??{},limit}}];

