CREATE TABLE IF NOT EXISTS n8n_elite_memory_events (
  id BIGSERIAL PRIMARY KEY,
  request_id TEXT NOT NULL DEFAULT '',
  key TEXT NOT NULL,
  value JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_n8n_elite_memory_events_request_id_id
  ON n8n_elite_memory_events(request_id, id DESC);
CREATE TABLE IF NOT EXISTS n8n_elite_memory_kv (
  key TEXT PRIMARY KEY,
  value JSONB NOT NULL DEFAULT '{}'::jsonb,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

